import{_ as r,o as a,c as o,a5 as t}from"./chunks/framework.CXroN2RO.js";const i="/study/images/os/windows-file-cache.svg",w=JSON.parse('{"title":"Windowsのファイルキャッシュと先読み","description":"","frontmatter":{"title":"Windowsのファイルキャッシュと先読み","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"os","summary":"同じ範囲の読み取りがRAMで満たされる条件、キャッシュマネージャーの先読み、アクセスヒントと非バッファーI/O、ゲームのロードを測る手順を扱う。","aliases":["ファイルキャッシュ","system file cache","Cache Manager","read-ahead","先読み","warm cache","cold cache","FILE_FLAG_SEQUENTIAL_SCAN","FILE_FLAG_RANDOM_ACCESS","FILE_FLAG_NO_BUFFERING","noncached I/O"],"verification":"MicrosoftのWindows APIとドライバー資料に照合（2026-11-06）"}},"headers":[],"relativePath":"os/windows-file-cache.md","filePath":"os/windows-file-cache.md"}'),n={name:"os/windows-file-cache.md"};function s(l,e,c,d,f,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="windowsのファイルキャッシュと先読み" tabindex="-1">Windowsのファイルキャッシュと先読み <a class="header-anchor" href="#windowsのファイルキャッシュと先読み" aria-label="Permalink to &quot;Windowsのファイルキャッシュと先読み&quot;">​</a></h1><p>Windowsで同じファイル範囲を二度読むと、二度目は<strong>すでにRAMにあるデータ</strong>から結果を返せることがあります。キャッシュマネージャー（Cache Manager）はファイルシステムと協力してデータをキャッシュし、後続の範囲を先読みすることもあります。ここではローカルストレージ上の通常ファイルを例に、どの範囲がいつRAMにあるかを追います。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/file-caching" target="_blank" rel="noreferrer">Microsoft: File Caching</a> · <a href="/study/os/file-read-journey.html">読み取りAPIの基本</a></p><h2 id="必要な範囲を取り寄せ、残っていれば再利用する" tabindex="-1">必要な範囲を取り寄せ、残っていれば再利用する <a class="header-anchor" href="#必要な範囲を取り寄せ、残っていれば再利用する" aria-label="Permalink to &quot;必要な範囲を取り寄せ、残っていれば再利用する&quot;">​</a></h2><p>例えば、レベルのパックファイル内の範囲Aを <code>ReadFile</code> で読みます。必要なデータがRAMにない場合、ファイルシステムとストレージの層を通して取得します。次に同じ範囲を要求し、必要なページがまだRAMにあれば、Windowsはファイルデータをそこから返せます。一部のページだけが残っていれば、足りない部分の取得が必要になることもあります。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/file-caching" target="_blank" rel="noreferrer">Microsoft: File Caching</a></p><figure class="study-figure"><img src="'+i+'" alt="最初の読み取りで範囲AがRAMにないときはストレージから取得し、後続のBを先読みする場合がある。再読み取りでAがまだRAMにある場合は、Aをキャッシュからアプリのバッファに返す。" width="760" height="524" loading="lazy"><figcaption>最初の読み取りがキャッシュミス、二度目がキャッシュヒットになった場合の概念図です。<a href="/study/images/os/windows-file-cache.svg" target="_blank" rel="noopener noreferrer">読み取り経路の図を拡大</a></figcaption></figure><p><strong>常駐</strong>はページの内容が物理メモリにある状態です。ファイルを開くと、その内容を扱うための情報が用意されます。必要なページがRAMに載る時点や、再利用されるまで残る期間は、アクセスの履歴とメモリの状況で変わります。ページがワーキングセットから外れた後もRAMに残る場合があり、その間は再び使えます。アプリが <code>CloseHandle</code> して開き直す場合も、ファイルの内容がすでにRAMにある可能性があります。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/file-caching" target="_blank" rel="noreferrer">Microsoft: File Caching</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/memory/working-set" target="_blank" rel="noreferrer">Microsoft: Working Set</a></p><p>仮想アドレスにファイルの範囲を対応付ける場合も、アクセスしたときにページが必要になります。ページフォルトにはRAMに残っているページを使う場合と、保存先からページ内容を取り寄せる場合があります。ある時点でどのファイルのページがRAMにあるかは、SysinternalsのRAMMapの <code>File Summary</code> や <code>File Details</code> で調べられます。個々の読み取りの前後関係を追うには、時系列のトレースを使います。<a href="/study/os/memory-mapped-files.html">メモリマップドファイル</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/memory/working-set" target="_blank" rel="noreferrer">Microsoft: Working Set</a> · <a href="https://learn.microsoft.com/en-us/sysinternals/downloads/rammap" target="_blank" rel="noreferrer">Microsoft: RAMMap</a></p><h2 id="先読みとアクセスパターンのヒント" tabindex="-1">先読みとアクセスパターンのヒント <a class="header-anchor" href="#先読みとアクセスパターンのヒント" aria-label="Permalink to &quot;先読みとアクセスパターンのヒント&quot;">​</a></h2><p>先読み（read-ahead）は後で要求されそうなファイル範囲をあらかじめ取得する処理です。例えばアプリが範囲Aに続いてBを読むとき、その時点でBを取得済みなら待ち時間を短くできます。先読みした範囲を使わなくても、取得に使った帯域とキャッシュ領域は消費します。Windowsやファイルシステムが先読みの範囲やタイミングを決めるため、アプリが要求したバイト数と下位で取得したバイト数は異なり得ます。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/ddi/ntifs/nf-ntifs-ccschedulereadahead" target="_blank" rel="noreferrer">Microsoft: CcScheduleReadAhead</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/ddi/ntifs/nf-ntifs-ccsetreadaheadgranularity" target="_blank" rel="noreferrer">Microsoft: CcSetReadAheadGranularity</a></p><table tabindex="0"><thead><tr><th><code>CreateFileW</code> の指定</th><th>想定する使い方</th></tr></thead><tbody><tr><td>どちらのヒントも指定しない</td><td>OSの標準のキャッシュ方針を使う。読み方が混在する場合や比較実験の基準にできる。</td></tr><tr><td><code>FILE_FLAG_SEQUENTIAL_SCAN</code></td><td>先頭から末尾へ進む読み方を伝える。大きなファイルを前方に向かって走査する処理に合う。</td></tr><tr><td><code>FILE_FLAG_RANDOM_ACCESS</code></td><td>離れたオフセットへ飛ぶ読み方を伝える。Windows Serverの資料では、この指定でキャッシュマネージャーがファイルデータの先読みを抑えると説明している。</td></tr></tbody></table><p>ヒントを使う場合は、ファイルを開くときに読み方に合う方を一つ選びます。<code>FILE_FLAG_RANDOM_ACCESS</code> でも、すでにキャッシュにあるデータは利用できます。キャッシュ保持への影響はWindowsの版によって異なり、大きなファイルを多数開く構成ではメモリ使用量も測ります。<a href="https://learn.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-createfilew#caching-behavior" target="_blank" rel="noreferrer">Microsoft: CreateFileW のキャッシュ動作</a> · <a href="https://learn.microsoft.com/en-us/windows-server/administration/performance-tuning/subsystem/cache-memory-management/troubleshoot#system-file-cache-contains-memory-mapped-files" target="_blank" rel="noreferrer">Microsoft: Windows Serverのキャッシュ調査</a></p><h2 id="osのデータキャッシュを迂回する場合" tabindex="-1">OSのデータキャッシュを迂回する場合 <a class="header-anchor" href="#osのデータキャッシュを迂回する場合" aria-label="Permalink to &quot;OSのデータキャッシュを迂回する場合&quot;">​</a></h2><p><code>FILE_FLAG_NO_BUFFERING</code> を付けて開いたハンドルから読み取ると、Windowsのファイルデータキャッシュを迂回します。比較する場合は、通常の読み取りとは別の経路として測ります。ファイルシステムのメタデータやデバイス側のキャッシュは別の層です。例えばOSがデバイスに読み取りを渡したあと、機器が保持していたデータで応答できる場合があります。<a href="https://learn.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-createfilew#caching-behavior" target="_blank" rel="noreferrer">Microsoft: CreateFileW のキャッシュ動作</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/fileio/file-buffering" target="_blank" rel="noreferrer">Microsoft: File Buffering</a></p><p>この指定では<strong>ファイル内オフセット、要求サイズ、バッファのアドレス</strong>をそれぞれ確認します。オフセットとサイズは対象ボリュームのセクターサイズの倍数にします。バッファのアドレスについては、Microsoftはストレージの物理セクター境界にそろえるよう推奨しています。論理セクターと物理セクターはサイズが異なる場合があるため、実際の対象で照会します。例えば論理が512バイト、物理が4,096バイトなら、オフセット8,192、要求サイズ4,096、4,096バイト境界にそろえたバッファは、それぞれの条件を満たします。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/file-buffering#alignment-and-file-access-requirements" target="_blank" rel="noreferrer">Microsoft: File Bufferingのアラインメント要件</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/winbase/ns-winbase-file_storage_info" target="_blank" rel="noreferrer">Microsoft: セクター情報を照会するFILE_STORAGE_INFO</a></p><h2 id="計測で初回と再読み取りを比べる" tabindex="-1">計測で初回と再読み取りを比べる <a class="header-anchor" href="#計測で初回と再読み取りを比べる" aria-label="Permalink to &quot;計測で初回と再読み取りを比べる&quot;">​</a></h2><p>初回と再読み取りで同じファイル、範囲、要求サイズを使い、要求時刻、完了時刻、読めたバイト数を記録します。<strong>コールド</strong>は対象範囲が比較対象のキャッシュにない状態、<strong>ウォーム</strong>は必要なデータがすでにある状態です。初回でも、ファイルを作った直後や、別のプロセスが先に読んだ範囲はウォームになり得ます。記録の上では「初回」「再読み取り」という実行順と、トレースから推定したキャッシュ状態を分けます。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/file-caching" target="_blank" rel="noreferrer">Microsoft: File Caching</a></p><p>アプリの所要時間、ファイル操作のトレース、OSが記録したディスクI/Oの時系列を見比べます。同じ範囲の要求が完了し、対応するディスク読み取りが再試行で減った場合は、キャッシュ再利用を説明する材料になります。先読みが計測区間の外で済んでいた可能性や、記録できたイベントの種類も合わせて確認します。<a href="/study/tools/windows/file-io-tracing.html">WindowsでファイルI/Oを計測する</a> · <a href="/study/practice/io/file-io-trace-observation.html">ファイル読み取りをトレースで観察する実践</a></p><h2 id="ゲームのアセットで読み取りの単位を決める" tabindex="-1">ゲームのアセットで読み取りの単位を決める <a class="header-anchor" href="#ゲームのアセットで読み取りの単位を決める" aria-label="Permalink to &quot;ゲームのアセットで読み取りの単位を決める&quot;">​</a></h2><p>パックファイルから近い範囲を何度も小分けに読む場合は、一つの要求にまとめるとAPI呼び出しや完了処理を減らせます。離れた範囲まで広げると使わないデータを読むので、まとめる前後で要求数と実際の読取量を比べます。ゲーム側が優先度の低い先読みでキューを埋めると、あとから必要になった要求が待つことがあります。同時発行数と保持する受取バッファの総量に上限を設け、長く待った要求やフレーム時間も確認します。例えば最大8件に各256 KiBを用意すると、読み取り中の受取バッファだけで最大2 MiBです。完了後に展開を待つデータには別の上限を設けます。<a href="/study/os/asynchronous-file-io.html">非同期I/Oの要求と完了</a> · <a href="/study/game/asset-loading.html">ゲームのアセットロード設計</a></p><p>アセットを使える時刻まで追うときは、読み取りの待ち、CPUでの展開、GPUへの転送と利用可能になる時刻を別々に記録します。読み取りが短縮されても、展開や転送で待っていればアセットが使える時刻はあまり変わりません。セーブデータの書き込みを調べる場合は、キャッシュから読める時点と障害後も残る条件を区別します。<a href="/study/game/asset-loading.html">アセットの状態と寿命</a> · <a href="/study/os/file-write-and-durability.html">ファイルの書き込みと永続化</a></p>',20)])])}const p=r(n,[["render",s]]);export{w as __pageData,p as default};
